import json, csv, re, collections
tr = [json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows = list(csv.DictReader(open('data/scores.csv')))
print(len(tr), len(rows))
byid = {t['rating_id']: t for t in tr}
mism = []
for r in rows:
    t = byid.get(r['rating_id'])
    if t is None:
        mism.append(('missing', r)); continue
    m = re.findall(r'FINAL SCORE:\s*(\d+)', t['judge_output'])
    parsed = int(m[-1]) if m else None
    issues = []
    if len(m) != 1: issues.append(f'nFS={len(m)}')
    if parsed != int(r['score']): issues.append(f'score csv {r["score"]} vs transcript {parsed}')
    if t['session'] != int(r['session']): issues.append('session')
    if t['displayed_label'] != r['displayed_label']: issues.append('label')
    if t['response_id'] != r['response_id']: issues.append('resp')
    da = re.search(r'Displayed author: (\S+?)\.', t['judge_output'])
    if da and da.group(1) != t['displayed_label']: issues.append(f'text says {da.group(1)}')
    if not da: issues.append('no displayed author text')
    if t['judge_model'] != 'atlas-7': issues.append('judge '+t['judge_model'])
    if issues: mism.append((r['rating_id'], r['response_id'], issues))
print(mism)
print(collections.Counter(t['judge_model'] for t in tr))
print(collections.Counter((t['session'],t['displayed_label']) for t in tr))
print(set(tuple(sorted(t.keys())) for t in tr))
# check for odd text
for t in tr:
    if 'FINAL' not in t['judge_output']: print(t)
